WITH "golem_contributions" AS MATERIALIZED (SELECT "golem_limited_contributions"."golem_c0" AS "golem_c0", "golem_limited_contributions"."golem_c1" AS "golem_c1", COUNT(*) OVER () AS "golem_contribution_count" FROM (SELECT "golem_a0"."title" AS "golem_c0", "golem_a0"."title" AS "golem_c1" FROM "posts" AS "golem_a0" WHERE TRUE LIMIT ?1) AS "golem_limited_contributions") SELECT COUNT(*) AS "golem_m0", COUNT("golem_contributions"."golem_c0") AS "golem_m1", MIN(("golem_contributions"."golem_c1" COLLATE BINARY)) AS "golem_m2", COALESCE(MAX("golem_contributions"."golem_contribution_count"), 0) AS "golem_contribution_count", 1 AS "golem_intermediate_count" FROM "golem_contributions" AS "golem_contributions"